import type { LessonLayoutItem, QuestionSlot } from "@/data/content";
import type { LessonBank } from "./money-basics";

/**
 * RE5 Mock Exam B — bank-backed. Deliberately harder than Mock A.
 *
 * Same structure as Mock A: **50 slots × 2 variants = a 100-question pool**,
 * one variant drawn per slot per attempt, so every sitting is a different
 * full-length paper over identical topic coverage.
 *
 * This paper leans on longer scenarios, EXCEPT/NOT framing, and distractors
 * that stay defensible until the exact rule is applied.
 *
 * variantId prefix: `r5b-`.
 */
const info = (title: string, content: string): LessonLayoutItem => ({ type: "info", title, content });

const S = (n: number, conceptId: string, v1: QuestionSlot["variants"][number]["step"], v2: QuestionSlot["variants"][number]["step"]): QuestionSlot => ({
  slotId: `re5-exam-prep/mock-b/q${n}`,
  conceptId,
  variants: [
    { variantId: `r5b-q${n}-v1`, step: v1 },
    { variantId: `r5b-q${n}-v2`, step: v2 },
  ],
});

const mockBSlots: QuestionSlot[] = [
  S(1, "fais-definitions",
    { type: "scenario", question: "A friend asks you over coffee, with no client relationship, whether Fund X is 'a good buy'. You say 'yes, definitely put your money there.' Does FAIS apply?", options: ["Yes. A recommendation about a product is advice wherever it is given", "No, because the setting was social and informal", "No, FAIS applies only to advice given in writing", "Only if your friend actually invests"], correct: 0, feedback: { correct: "Advice is defined by what you said, not where you said it. The informal setting is no defence.", incorrect: "A recommendation of a financial nature is advice regardless of the setting or the format." } },
    { type: "scenario", question: "You post on social media that a particular ETF is 'the one everyone should be holding'. What is the FAIS risk?", options: ["It may constitute advice", "None, because social media is unregulated", "None, because you named no client", "It is only a risk if someone loses money"], correct: 0, feedback: { correct: "Right. A public recommendation can still be advice, and it comes with duties you can't discharge to an unknown audience.", incorrect: "It can amount to advice. The medium doesn't exempt you, and losses aren't what triggers the duty." } }),
  S(2, "fais-definitions",
    { type: "mcq", question: "Which is an intermediary service rather than advice?", options: ["Collecting premiums on the insurer's behalf", "Recommending the client switch to a cheaper policy", "Explaining which of two products better suits the client", "Proposing that a policy be replaced"], correct: 0, feedback: { correct: "No recommendation is involved. You are simply acting between client and supplier.", incorrect: "Collecting premiums is an intermediary service. The other three all involve a recommendation." } },
    { type: "scenario", question: "You complete and submit a client's claim form exactly as they instruct, adding no recommendation. That is:", options: ["An intermediary service", "Advice", "Outside FAIS entirely", "A discretionary service"], correct: 0, feedback: { correct: "Right. Acting on instruction between client and supplier, with no recommendation, is intermediary service.", incorrect: "It's an intermediary service: still regulated, but not advice." } }),
  S(3, "fais-purpose",
    { type: "scenario", question: "An insurer is well capitalised but its call centre routinely talks customers out of valid claims. Which regulator owns this problem, and why?", options: ["The FSCA", "The Prudential Authority, because it supervises insurers", "The FAIS Ombud, because claims are involved", "The National Credit Regulator"], correct: 0, feedback: { correct: "Twin Peaks splits it cleanly: the Prudential Authority worries about whether the firm can pay, the FSCA about whether it behaves.", incorrect: "It's a conduct failure, so the FSCA. The Prudential Authority's mandate is solvency, and the Ombud handles individual complaints rather than systemic conduct." } },
    { type: "scenario", question: "A bank is financially sound but systematically mis-sells a product. Which regulator's mandate does that fall under?", options: ["The FSCA", "The Prudential Authority", "The National Credit Regulator", "SARS"], correct: 0, feedback: { correct: "Right. Solvency is fine, conduct is not. That's squarely the FSCA's territory.", incorrect: "Mis-selling is a conduct failure, so it sits with the FSCA." } }),
  S(4, "fsp-categories",
    { type: "mcq", question: "A Category IV FSP conducts:", options: ["Assistance business", "Discretionary investment management", "Platform administration", "Hedge fund management"], correct: 0, feedback: { correct: "Category IV is assistance business, typically funeral policies.", incorrect: "Category IV is assistance business. II is discretionary, III administrative." } },
    { type: "scenario", question: "An FSP wants to both advise clients and manage their portfolios at its own discretion. What does it need?", options: ["Authorisation for both Category I and Category II", "Category I only", "Category III only", "Category IV only"], correct: 0, feedback: { correct: "Right. Advice and discretionary management are separate authorisations, and you need each one you actually use.", incorrect: "Both: Category I for advice and intermediary services, Category II for discretion." } }),
  S(5, "fsp-licence-action",
    { type: "mcq", question: "Which is NOT a ground to withdraw an FSP licence?", options: ["The FSP became profitable", "The FSP no longer complies with fit and proper requirements", "The licence was obtained on materially false information", "The FSP has seriously contravened the Act"], correct: 0, feedback: { correct: "Profitability is not a conduct matter. The other three are all genuine grounds.", incorrect: "Profitability is irrelevant to licensing. The other three are all valid grounds." } },
    { type: "scenario", question: "An FSCA inspection finds an FSP has had no compliance function for two years. What is the exposure?", options: ["It may face suspension or withdrawal for failing operational ability requirements", "Nothing, provided no client complained", "A warning letter only, by law", "It affects only the Key Individual personally"], correct: 0, feedback: { correct: "Right. Operational ability is a fit and proper pillar, and a sustained failure is a licensing issue.", incorrect: "It goes to operational ability and fit and proper status. Suspension or withdrawal is on the table." } }),
  S(6, "fit-and-proper",
    { type: "mcq", question: "A representative's honesty and integrity may be questioned by:", options: ["A conviction involving dishonesty", "A period of unemployment", "A change of FSP", "A low CPD score"], correct: 0, feedback: { correct: "Dishonesty offences go directly to whether the person can be trusted with clients' money.", incorrect: "A conviction involving dishonesty. Career events don't affect honesty and integrity." } },
    { type: "scenario", question: "A candidate discloses a fraud conviction from six years ago. How should the FSP treat it?", options: ["Assess it against the honesty and integrity requirement before appointment", "Ignore it, since it is historical", "Appoint them and disclose it to clients", "Refer the decision to the FAIS Ombud"], correct: 0, feedback: { correct: "Right. It must be properly assessed, it isn't an automatic bar, but it can't simply be waved through.", incorrect: "It must be assessed against honesty and integrity. Age alone doesn't neutralise a dishonesty conviction." } }),
  S(7, "fais-competence-cpd",
    { type: "mcq", question: "Competence timelines are measured from the:", options: ["Date of First Appointment (DOFA)", "Date the FSP was licensed", "First day of the CPD cycle", "Date the client relationship started"], correct: 0, feedback: { correct: "DOFA anchors the regulatory exam and qualification deadlines.", incorrect: "From DOFA: the Date of First Appointment." } },
    { type: "scenario", question: "A representative's DOFA was five years ago and they have no recognised qualification yet. What is the position?", options: ["They are within the six-year window, but running out of time", "They are already in breach", "The requirement no longer applies after five years", "The window restarts if they change FSP"], correct: 0, feedback: { correct: "Right, and changing employer does not reset the clock, DOFA follows the person.", incorrect: "The window is six years from DOFA, and it doesn't reset on a change of FSP." } }),
  S(8, "fais-competence-cpd",
    { type: "mcq", question: "How is a representative's required CPD hours per cycle determined?", options: ["By how many classes of business they are authorised for", "By their annual commission", "By their years of service", "By the size of their FSP"], correct: 0, feedback: { correct: "The requirement scales with the breadth of authorisation, 6, 12 or 18 hours per cycle.", incorrect: "It scales with the number of classes of business you're authorised for." } },
    { type: "mcq", question: "Class-of-business training must be completed:", options: ["Before rendering advice in that class of business", "Within a year of starting", "Only when the FSCA requests it", "At the end of each CPD cycle"], correct: 0, feedback: { correct: "Right. It's a precondition to advising in that class, not something you catch up on later.", incorrect: "Before you render advice in that class. It's a precondition, not a follow-up." } }),
  S(9, "fais-competence-cpd",
    { type: "mcq", question: "Which is required BEFORE recommending a specific product?", options: ["Product-specific training on that product", "A full CPD cycle", "A postgraduate qualification", "FSCA written approval"], correct: 0, feedback: { correct: "You must understand the specific product. This is separate from both CPD and class-of-business training.", incorrect: "Product-specific training. CPD and class-of-business training are separate requirements." } },
    { type: "scenario", question: "A representative is authorised for the correct class but has never been trained on the specific product they are about to recommend. Can they proceed?", options: ["No. Product-specific training is required first", "Yes, class authorisation is enough", "Yes, if a Key Individual approves", "Yes, if the client is told"], correct: 0, feedback: { correct: "Right. Class authorisation is necessary but not sufficient for a specific product recommendation.", incorrect: "No. Product-specific training is required on top of class-of-business authorisation." } }),
  S(10, "fais-representatives",
    { type: "scenario", question: "An FSP appoints a representative but forgets to add them to the register for three weeks. Which requirement is breached?", options: ["Updating the register within 15 days", "The 6-week complaints window", "The 6-year qualification deadline", "The 5-year record retention rule"], correct: 0, feedback: { correct: "Three weeks exceeds the 15-day window, so the register was inaccurate for the balance of that period.", incorrect: "The register must be updated within 15 days." } },
    { type: "mcq", question: "Why does the representative register matter so much?", options: ["It is the public record of who is authorised and for what", "It determines commission rates", "It sets CPD requirements", "It replaces the licence"], correct: 0, feedback: { correct: "Right. Clients and the regulator rely on it to know whether someone may lawfully act.", incorrect: "It's the authoritative record of who is authorised, for which services, and under what conditions." } }),
  S(11, "fit-and-proper",
    { type: "scenario", question: "A Key Individual discovers a representative lied about their qualifications on appointment. The most appropriate response is to:", options: ["Investigate, as they may no longer be fit and proper", "Ignore it if their sales are strong", "Quietly reassign them to administration", "Wait for the FSCA to raise it"], correct: 0, feedback: { correct: "Dishonesty at appointment goes straight to honesty and integrity, and the KI has an oversight duty to act.", incorrect: "Investigate. It goes to honesty and integrity, and the KI cannot simply let it pass." } },
    { type: "scenario", question: "The same investigation confirms the representative falsified the qualification. What is the likely outcome?", options: ["Debarment, following a procedurally fair process", "An immediate dismissal with no further steps", "A written warning only, by law", "Referral to the FAIS Ombud"], correct: 0, feedback: { correct: "Right, but the process must still be fair: notice, reasons and an opportunity to respond.", incorrect: "Debarment is likely, but only after a procedurally fair process. The Ombud handles client complaints, not this." } }),
  S(12, "fais-debarment",
    { type: "mcq", question: "In a debarment, the representative is entitled to:", options: ["Notice, reasons and an opportunity to respond", "A criminal trial first", "Six months' paid notice", "An automatic appeal to the High Court"], correct: 0, feedback: { correct: "Procedural fairness is mandatory because debarment ends the person's ability to work in the industry.", incorrect: "Notice, reasons and an opportunity to respond." } },
    { type: "scenario", question: "A representative resigns the day before a debarment hearing. Can the FSP still debar them?", options: ["Yes. Resignation does not defeat the debarment process", "No, they are no longer a representative", "Only with FSCA permission", "Only if they were employed for over a year"], correct: 0, feedback: { correct: "Right. Otherwise resigning would be an easy way to move to the next FSP with a clean slate.", incorrect: "Yes. Resignation doesn't prevent debarment for conduct that occurred while appointed." } }),
  S(13, "fais-debarment",
    { type: "scenario", question: "An FSP completes a debarment and decides to keep it quiet to protect the person's future prospects. What is wrong with that?", options: ["The FSCA must be notified and the register updated. Concealment leaves other FSPs exposed", "Nothing, debarment is an internal employment matter", "Only the affected clients needed telling", "It should have been published in a newspaper"], correct: 0, feedback: { correct: "The whole point of the notification is that the next FSP can see it. Discretion here defeats the mechanism.", incorrect: "Notify the FSCA and update the register. Keeping a debarment private is itself a compliance failure." } },
    { type: "scenario", question: "A candidate discloses a debarment that was lifted two years ago. How should the FSP treat it?", options: ["Assess it as part of good standing", "Disregard it entirely, as it has been lifted", "Refuse the appointment automatically", "Appoint them and notify the FSCA afterwards"], correct: 0, feedback: { correct: "Right. A lifted debarment isn't an automatic bar, but it's directly relevant history that must be weighed.", incorrect: "It remains relevant to good standing. It neither disqualifies automatically nor disappears from consideration." } }),
  S(14, "code-disclosures",
    { type: "scenario", question: "Every sentence in your presentation is factually correct, but the client walks away believing the product carries no downside. Have you complied with the Code?", options: ["No. The test is the impression created", "Yes, because nothing untrue was said", "Yes, provided the facts were sourced", "Only if the client later confirms understanding"], correct: 0, feedback: { correct: "This is the most common way disclosure fails: accurate components assembled into a misleading whole.", incorrect: "It's still a breach. The Code prohibits creating a misleading impression, however true the individual statements were." } },
    { type: "scenario", question: "You show a client a fund's best five-year period and omit its worst. Is that compliant?", options: ["No. Selective presentation creates a misleading impression", "Yes, the figures are accurate", "Yes, if the source is cited", "Yes, for experienced investors"], correct: 0, feedback: { correct: "Right. Accurate but cherry-picked figures breach the requirement that disclosure not be misleading.", incorrect: "It's not compliant. Accuracy of individual figures doesn't cure a misleading overall picture." } }),
  S(15, "code-disclosures",
    { type: "scenario", question: "A client asks what a product will cost them 'all in'. Which of these may you leave out of your answer?", options: ["Nothing material. Terms, fees, charges, penalties and risks all have to be covered", "Early-termination penalties, since they may never apply", "Ongoing platform fees, since the supplier sets them", "Risk warnings, if the client seems experienced"], correct: 0, feedback: { correct: "Anything that could reasonably affect the decision is material, including costs the client may never actually incur.", incorrect: "Nothing material may be omitted. Penalties, ongoing fees and risks are all part of the required disclosure." } },
    { type: "scenario", question: "A policy carries a heavy early-termination penalty. When must the client be told?", options: ["Before they commit", "Only if they later cancel", "Within five years", "Only if they ask"], correct: 0, feedback: { correct: "Right. Penalties are material terms, and disclosure after the fact is no disclosure at all.", incorrect: "Before commitment. Penalties are material terms requiring upfront disclosure." } }),
  S(16, "code-records-coi",
    { type: "mcq", question: "A fee negotiated directly with a client must be:", options: ["Agreed in writing and capable of being stopped by the client", "Fixed by the FSCA", "Paid only in cash", "Kept confidential from the product supplier"], correct: 0, feedback: { correct: "The client must both agree to it and be able to end it: otherwise it isn't really negotiated.", incorrect: "Agreed in writing, and the client must be able to stop it." } },
    { type: "scenario", question: "An adviser deducts an ongoing advice fee the client never agreed to in writing. This is:", options: ["A breach. Such fees require written agreement and must be stoppable", "Acceptable if the service is genuinely delivered", "Acceptable if the amount is small", "Acceptable if disclosed annually"], correct: 0, feedback: { correct: "Right. Delivering value doesn't retrospectively create the client's consent.", incorrect: "It's a breach. Negotiated fees require written agreement and must be capable of being stopped." } }),
  S(17, "code-suitability",
    { type: "scenario", question: "A client will discuss their goals but flatly refuses to disclose their debts. You proceed with a plan anyway. What must appear on the file?", options: ["A record of the refusal, the resulting limitation, and the risk warning you gave", "Nothing, the client chose not to disclose", "An estimate of their debt, clearly marked", "A note that the plan is provisional"], correct: 0, feedback: { correct: "You can act on incomplete information, but only if the gap and the warning are documented. That file note is your entire defence later.", incorrect: "The refusal, the limitation it creates and the warning you gave all have to be recorded. Estimates and vague 'provisional' labels don't cover it." } },
    { type: "scenario", question: "Two products both broadly fit the client, and you genuinely cannot tell which is better without information you don't have. What does the Code require?", options: ["Obtain the missing information before recommending either", "Recommend the cheaper one as a safe default", "Recommend both and let the client pick", "Recommend the one you know better"], correct: 0, feedback: { correct: "Suitability is a positive duty. Defaulting to 'cheaper' or 'familiar' substitutes a rule of thumb for the analysis you owe.", incorrect: "Get the missing information first. Neither price nor familiarity discharges the suitability duty." } }),
  S(18, "code-records-coi",
    { type: "scenario", question: "Your record of advice names the product sold and the date, and nothing else. An Ombud complaint arrives two years later. What is the weakness?", options: ["It shows no needs analysis, no options considered and no reasoning", "It should have included the commission", "It should have been countersigned", "It should have been sent to the FSCA"], correct: 0, feedback: { correct: "A record of advice exists to make your reasoning reviewable. One that records only the outcome proves nothing about how you got there.", incorrect: "The reasoning is missing: needs identified, options considered and why this recommendation. That's what a record of advice is for." } },
    { type: "scenario", question: "You keep a full record of advice on file but never give the client a copy. Is that compliant?", options: ["No. The client must be provided with it", "Yes, retention is the only requirement", "Yes, if the client did not request it", "Only if the advice was declined"], correct: 0, feedback: { correct: "Both limbs are required. Retention without provision leaves the client unable to check what you actually advised.", incorrect: "It must be provided to the client and retained by the provider. Retention alone is not enough." } }),
  S(19, "code-suitability",
    { type: "mcq", question: "Replacing one product with another triggers a duty to:", options: ["Compare and disclose the costs and implications of the replacement", "Obtain FSCA approval first", "Wait 30 days before implementing", "Refund all prior commission"], correct: 0, feedback: { correct: "Replacement is where churning risk lives, so the comparison and disclosure duties are explicit.", incorrect: "Compare the products and disclose the costs and implications of replacing." } },
    { type: "scenario", question: "You recommend a client cancel a 12-year-old policy and take a new one that pays you fresh commission. What must you do?", options: ["Compare both fully, disclose the costs and implications, and record why the switch is in the client's interest", "Proceed, since the new product is better", "Disclose only the new product's fees", "Nothing extra. It is a new sale"], correct: 0, feedback: { correct: "Right. Replacement plus fresh commission is the classic churning pattern, and it attracts the closest scrutiny.", incorrect: "Full comparison, disclosure of costs and implications, and a recorded rationale." } }),
  S(20, "code-records-coi",
    { type: "scenario", question: "An FSP stores all client records on one laptop with no backup. The laptop is stolen in year three. What requirement has been failed?", options: ["Records must be retrievable and safe from destruction for the full retention period", "Records must be stored on paper", "Records must be held offshore", "Records must be printed annually"], correct: 0, feedback: { correct: "Electronic storage is fine, but 'one device, no backup' fails the safe-from-destruction test long before the theft happens.", incorrect: "Retrievable and safe from destruction for the retention period. A single unbacked device satisfies neither." } },
    { type: "mcq", question: "The general record retention period under the General Code is:", options: ["5 years", "12 months", "3 years", "7 years"], correct: 0, feedback: { correct: "Right. The same five years FICA requires, which keeps the two regimes aligned.", incorrect: "Five years." } }),
  S(21, "code-records-coi",
    { type: "scenario", question: "An insurer offers you a free overseas holiday if you sell 50 of its policies this quarter. Accepting this is:", options: ["A prohibited interest that rewards volume over quality", "Acceptable if you disclose it afterwards", "Acceptable because it is not cash", "Acceptable if all 50 sales were suitable"], correct: 0, feedback: { correct: "The structure is the problem: it rewards quantity, which is exactly what the COI rules prohibit.", incorrect: "It's a prohibited volume-based incentive, whether or not it takes a cash form." } },
    { type: "mcq", question: "Which is expressly restricted by the conflict of interest rules?", options: ["Rewarding quantity of business over quality", "Paying a fixed salary", "Reimbursing actual travel costs", "Funding accredited training"], correct: 0, feedback: { correct: "Right. Volume-driven rewards distort advice, which is the mischief the rules address.", incorrect: "Rewards based on volume rather than quality of business." } }),
  S(22, "code-records-coi",
    { type: "mcq", question: "A conflict of interest is:", options: ["A situation where the provider's own interest may influence the advice given", "Any disagreement with a client", "A complaint about fees", "A dispute between two FSPs"], correct: 0, feedback: { correct: "It's about influence, not wrongdoing. The conflict exists whether or not it changes the advice.", incorrect: "A situation in which the provider's interest may influence the advice or service." } },
    { type: "scenario", question: "Your FSP is part-owned by a product supplier whose funds you recommend. What does the Code require?", options: ["Identify the conflict, mitigate it where possible, and disclose it to clients", "Stop recommending those funds entirely", "Nothing, since ownership is public", "Disclose it only if a client asks"], correct: 0, feedback: { correct: "Right. Ownership links are a textbook conflict, manageable, but only if identified and disclosed.", incorrect: "Identify, mitigate and disclose. It doesn't automatically prohibit the recommendation." } }),
  S(23, "tcf-complaints",
    { type: "scenario", question: "A review finds advisers routinely recommend the same product to every client regardless of circumstances. Which TCF outcome does that offend most directly?", options: ["Outcome 4. Advice must be suitable and take the customer's circumstances into account", "Outcome 1: culture", "Outcome 2. Products meet the needs of identified groups", "Outcome 5, products perform as expected"], correct: 0, feedback: { correct: "One-size-fits-all recommendations are the textbook Outcome 4 failure, whatever the product's own merits.", incorrect: "Outcome 4 governs suitability of advice. The others concern culture, product design and performance." } },
    { type: "mcq", question: "TCF Outcome 6 is concerned with:", options: ["No unreasonable barriers to switching, claiming or complaining after the sale", "Product design", "Clear information before the sale", "Firm culture"], correct: 0, feedback: { correct: "Right. Post-sale barriers are where unfair treatment is easiest to hide.", incorrect: "Outcome 6 targets unreasonable post-sale barriers." } }),
  S(24, "code-general-duty",
    { type: "scenario", question: "A marketing team wants to run 'up to 30% returns' with a small-print disclaimer that returns are not guaranteed. Is that acceptable?", options: ["No. A headline the disclaimer contradicts still creates a misleading impression", "Yes, the disclaimer cures it", "Yes, because 'up to' is not a promise", "Yes, if aimed at experienced investors"], correct: 0, feedback: { correct: "A disclaimer that fights the headline doesn't rescue it. What matters is the impression the advertisement actually leaves.", incorrect: "It's still misleading. Small print cannot undo a headline the reader will remember." } },
    { type: "scenario", question: "An adviser posts a client's exceptional return on social media as an example of 'what we achieve'. What is the compliance problem?", options: ["It presents an unrepresentative result as typical", "Nothing, since the figure is genuine", "Only that client consent was needed", "Only that it should have been on the firm's website"], correct: 0, feedback: { correct: "A real number can still mislead if it implies a typical outcome. Advertising is held to the same honesty standard as advice.", incorrect: "Presenting an outlier as representative is misleading, and the required cautionary wording is missing. Consent isn't the issue." } }),
  S(25, "code-disclosures",
    { type: "mcq", question: "In direct marketing, at the START of the contact the provider must disclose:", options: ["Their identity, the purpose of the call and the client's rights", "The commission they will earn", "Their full licence history", "The product supplier's financials"], correct: 0, feedback: { correct: "The client must know immediately who is calling and why, before any pitch begins.", incorrect: "Identity, purpose of the contact and the client's rights. Right at the start." } },
    { type: "scenario", question: "A cold caller launches straight into a product pitch without identifying themselves or the firm. What is wrong?", options: ["Identity and purpose must be disclosed at the start of the contact", "Nothing, provided the product details are accurate", "They should have called during business hours", "They needed the client's written consent"], correct: 0, feedback: { correct: "Right. The disclosure comes first, otherwise the client can't assess anything that follows.", incorrect: "Identity, purpose and client rights must come at the start of direct marketing contact." } }),
  S(26, "fais-ombud",
    { type: "mcq", question: "The FAIS Ombud resolves complaints:", options: ["Fairly, economically and expeditiously", "Only through formal litigation", "Only where losses exceed R100 000", "Only for Category I FSPs"], correct: 0, feedback: { correct: "That's the statutory standard: an accessible alternative to court, not a copy of it.", incorrect: "Fairly, economically and expeditiously. That's the Ombud's mandate." } },
    { type: "mcq", question: "The FAIS Ombud's service to complainants is:", options: ["Free of charge", "Charged at a percentage of the award", "Charged at a fixed fee", "Free only for amounts under R50 000"], correct: 0, feedback: { correct: "Right. Cost is not a barrier to complaining, which is central to the Ombud's purpose.", incorrect: "It's free to the complainant." } }),
  S(27, "fais-ombud",
    { type: "scenario", question: "A client's loss is R4.2 million from poor advice. The Ombud can still determine it if the client:", options: ["Abandons the portion above R3.5 million", "Splits it into two complaints", "Obtains FSCA consent", "Waits three years"], correct: 0, feedback: { correct: "Abandoning the excess brings the claim within the cap. Splitting a single claim will not.", incorrect: "By abandoning the amount above the R3.5 million cap. Splitting one claim isn't permitted." } },
    { type: "scenario", question: "Two clients were given the same poor advice by the same adviser and each lost R2 million. What can the Ombud do?", options: ["Determine each complaint separately", "Cap the combined total at R3.5 million", "Decline both as too large", "Refer both to the High Court"], correct: 0, feedback: { correct: "The cap is per complaint, not per adviser or per event, so each client's claim is assessed on its own.", incorrect: "The R3.5 million cap applies to each complaint. Two separate complainants are two separate matters." } }),
  S(28, "fais-ombud",
    { type: "mcq", question: "A complaint the Ombud will likely decline is one that:", options: ["Is already before a court", "Concerns a complex structured product", "Involves a small monetary amount", "Was lodged by email"], correct: 0, feedback: { correct: "The Ombud will not run in parallel with litigation on the same matter.", incorrect: "One already before a court. Complexity, size and format are not bars." } },
    { type: "mcq", question: "The Ombud may decline a complaint where the client became aware of the facts more than:", options: ["3 years ago", "6 months ago", "12 months ago", "5 years ago"], correct: 0, feedback: { correct: "Right. Three years from awareness is the prescription period.", incorrect: "Three years. The prescription period runs from when the client became aware." } }),
  S(29, "fais-ombud",
    { type: "scenario", question: "An FSP believes an Ombud determination against it was wrongly decided. What is the correct next step?", options: ["Apply to the Financial Services Tribunal for reconsideration", "Ignore it, since determinations are advisory", "Sue the complainant", "Ask the FSCA to overturn it"], correct: 0, feedback: { correct: "The Tribunal is the reconsideration forum. Ignoring it is not an option. A determination is enforceable like a court order.", incorrect: "The Financial Services Tribunal. Determinations are binding, so they must be challenged rather than ignored." } },
    { type: "mcq", question: "A determination amount that an FSP fails to pay can be:", options: ["Enforced as if it were a court order", "Written off after 12 months", "Recovered only by a new civil claim", "Collected by the FSCA on the client's behalf"], correct: 0, feedback: { correct: "Right. That enforceability is what gives a determination real weight.", incorrect: "Enforced as though it were a court order. No fresh civil claim is needed." } }),
  S(30, "tcf-complaints",
    { type: "scenario", question: "An FSP has a written complaints procedure, but it exists only in a staff manual clients never see. What is the failing?", options: ["The procedure must be accessible to clients, not just documented internally", "Nothing, provided complaints are resolved", "It should be approved by the FSCA", "It should be published in the Gazette"], correct: 0, feedback: { correct: "Both limbs matter: documented and accessible. A process a client cannot find is not a process they can use.", incorrect: "It has to be accessible to clients as well as documented. Internal-only defeats the purpose." } },
    { type: "mcq", question: "Internal complaints records must be retained for:", options: ["5 years", "6 months", "12 months", "10 years"], correct: 0, feedback: { correct: "Right. Five years, consistent with the Code's general retention period.", incorrect: "Five years." } }),
  S(31, "fica",
    { type: "mcq", question: "Under FICA, an FSP that is an accountable institution must NOT:", options: ["Tip off a client that a suspicious transaction report was filed", "Verify client identity", "Maintain an RMCP", "Report cash above the threshold"], correct: 0, feedback: { correct: "Tipping off is the prohibition. The other three are obligations.", incorrect: "Tipping off is prohibited; the rest are all requirements." } },
    { type: "scenario", question: "After filing an STR, a client asks whether you reported anything. The correct response is to:", options: ["Not disclose it", "Confirm it, since honesty is a FAIS duty", "Say you cannot recall", "Refer them to the FIC"], correct: 0, feedback: { correct: "Right. The FAIS honesty duty does not override a statutory prohibition, and referring them to the FIC would itself signal the report.", incorrect: "Do not disclose it. Tipping off is a criminal offence, and pointing them to the FIC amounts to the same thing." } }),
  S(32, "fica",
    { type: "scenario", question: "A client makes a large cash deposit that is entirely legitimate and well explained, but above the prescribed threshold. What must you do?", options: ["File a cash threshold report. It is triggered by the amount, not by suspicion", "Nothing, since there is no suspicion", "File a suspicious transaction report", "Record it internally only"], correct: 0, feedback: { correct: "A CTR is automatic above the threshold. An innocent explanation doesn't switch off the reporting obligation.", incorrect: "A cash threshold report is required by amount alone. Suspicion is what triggers an STR, separately." } },
    { type: "mcq", question: "What distinguishes a CTR from an STR?", options: ["A CTR is triggered by amount; an STR is triggered by suspicion at any amount", "A CTR is voluntary", "An STR only applies to cash", "They are the same report"], correct: 0, feedback: { correct: "Right. A transaction can require both, one, or neither.", incorrect: "Amount versus suspicion. An STR has no minimum value and isn't limited to cash." } }),
  S(33, "fica",
    { type: "scenario", question: "A trust opens an account. Verifying the trustees alone is not enough. Which FICA obligation requires you to go further?", options: ["Customer due diligence", "The record-keeping obligation", "The cash threshold reporting obligation", "The RMCP review obligation"], correct: 0, feedback: { correct: "CDD asks who ultimately owns or controls the client, precisely what a trust or company structure can obscure.", incorrect: "Customer due diligence requires establishing beneficial ownership behind the legal entity." } },
    { type: "scenario", question: "A company opens an account and names a director as the contact. What else must you establish?", options: ["Who ultimately owns or controls the company", "The company's profit forecast", "The director's credit score", "The company's auditor"], correct: 0, feedback: { correct: "Right. Beneficial ownership is exactly what a corporate structure can be used to obscure.", incorrect: "The beneficial owner, who ultimately owns or controls the entity." } }),
  S(34, "fica",
    { type: "scenario", question: "A valuable long-standing client refuses to update their FICA documents, saying you have known them for a decade. What must you do?", options: ["Decline to continue the relationship until verification is complete", "Continue, given the length of the relationship", "Accept a signed declaration in place of documents", "Continue but cap their transaction size"], correct: 0, feedback: { correct: "Familiarity is not verification. The obligation applies to existing relationships, not just new ones.", incorrect: "The relationship may not continue without the required verification, however long-standing the client." } },
    { type: "mcq", question: "FICA records are generally retained for:", options: ["5 years", "12 months", "3 years", "Indefinitely"], correct: 0, feedback: { correct: "Right. Five years, aligned with the FAIS General Code.", incorrect: "Five years." } }),
  S(35, "fais-purpose",
    { type: "mcq", question: "To pass the RE5 a candidate must answer at least:", options: ["33 of 50 questions correctly", "25 of 50", "40 of 50", "45 of 50"], correct: 0, feedback: { correct: "33 out of 50, which is 66%.", incorrect: "33 of 50, a 66% pass mark." } },
    { type: "mcq", question: "The RE5 pass mark expressed as a percentage is:", options: ["66%", "50%", "75%", "80%"], correct: 0, feedback: { correct: "Right: 33 correct out of 50 questions.", incorrect: "66%, which is 33 of the 50 questions." } }),
  S(36, "fais-purpose",
    { type: "mcq", question: "The RE5 exam consists of:", options: ["50 questions", "30 questions", "80 questions", "100 questions"], correct: 0, feedback: { correct: "50 questions, with 33 correct required to pass.", incorrect: "50 questions." } },
    { type: "scenario", question: "A candidate revises hard on fund performance analysis and product features, then fails the RE5. What did they misjudge?", options: ["The RE5 examines the FAIS framework and conduct obligations, not product or investment technique", "They needed more mathematics", "They should have studied company law", "The exam is mostly about underwriting"], correct: 0, feedback: { correct: "It's a regulatory exam about how you must behave, not a test of investment skill. That misreading is the most common cause of failure.", incorrect: "The RE5 covers the FAIS framework and a representative's conduct obligations, not product or investment technique." } }),
  S(37, "code-suitability",
    { type: "scenario", question: "A product falls just outside your area of expertise and you are not confident you can assess its suitability. What does the Code expect?", options: ["Decline or refer to someone competent", "Recommend it and disclose your uncertainty", "Recommend it if a colleague approves", "Recommend the nearest product you do understand"], correct: 0, feedback: { correct: "Due skill, care and diligence means recognising the edge of your competence. A caveat doesn't transfer the duty to the client.", incorrect: "Decline or refer. Neither a disclosure of uncertainty nor a colleague's sign-off discharges your own suitability duty." } },
    { type: "scenario", question: "A client wants a product that is clearly unsuitable, and no warning changes their mind. You may:", options: ["Proceed on an against-advice basis, fully recorded", "Refuse and terminate the relationship immediately", "Proceed and record it as suitable", "Amend their risk profile to fit"], correct: 0, feedback: { correct: "Right, and never restyle the transaction as suitable or adjust the profile. That's what turns a defensible file into an indefensible one.", incorrect: "Proceed on a properly recorded against-advice basis. Never re-label it as suitable." } }),
  S(38, "tcf-complaints",
    { type: "scenario", question: "An unhappy client says they 'want this looked at by someone senior' but never uses the word 'complaint'. How should you treat it?", options: ["As a complaint, engage the internal process and explain their rights", "As feedback, requiring no formal action", "As a complaint only once they put it in writing", "As a matter for the Ombud directly"], correct: 0, feedback: { correct: "Substance beats labels. Waiting for the magic word is exactly the barrier TCF Outcome 6 is aimed at.", incorrect: "It's a complaint in substance. Treat it as one, engage the internal process and explain their escalation rights." } },
    { type: "scenario", question: "You resolve a written complaint fully within three weeks and the client is satisfied. Must you tell them about the Ombud?", options: ["No. That right arises when a complaint is not resolved satisfactorily", "Yes, in every case", "Yes, but only in writing", "Only above R100 000"], correct: 0, feedback: { correct: "Right. The escalation notice attaches to unresolved complaints.", incorrect: "The duty arises where the complaint isn't resolved to the client's satisfaction." } }),
  S(39, "fais-representatives",
    { type: "mcq", question: "A representative under supervision must:", options: ["Be supervised in line with the FSCA's supervision requirements", "Work entirely unsupervised after six months", "Handle only existing clients", "Be paid a reduced commission by law"], correct: 0, feedback: { correct: "The supervision arrangement itself is prescribed, it isn't informal mentoring.", incorrect: "Supervision must follow the FSCA's prescribed requirements." } },
    { type: "scenario", question: "A supervised representative's file shows no supervision records at all. What is the problem?", options: ["Supervision must be documented as well as performed", "Nothing, provided the advice was sound", "Only the KI is affected", "It matters only if a client complains"], correct: 0, feedback: { correct: "Right. Undocumented supervision is indistinguishable from no supervision when the regulator looks.", incorrect: "Supervision must be documented. Without records, it can't be demonstrated." } }),
  S(40, "code-records-coi",
    { type: "scenario", question: "Two suitable products would both serve the client, but one pays you materially more. What does the Code require?", options: ["Disclose the remuneration difference and ensure the recommendation is driven by suitability, not by your earnings", "Recommend the higher-paying one, since both are suitable", "Recommend the lower-paying one to avoid any conflict", "Say nothing, as both meet the client's needs"], correct: 0, feedback: { correct: "The conflict must be disclosed and managed. Note that automatically picking the cheaper option isn't the answer either: suitability decides.", incorrect: "Disclose the difference and let suitability drive the choice. Silence breaches the remuneration and conflict duties." } },
    { type: "scenario", question: "A client asks how you are paid on a policy you have recommended. You should:", options: ["Tell them the basis and amount of your remuneration", "Say it is between you and the insurer", "Give a general range only", "Explain it after the policy is issued"], correct: 0, feedback: { correct: "Right. Remuneration disclosure is a duty regardless of whether the client thinks to ask.", incorrect: "Disclose the basis and amount. Vagueness and post-sale disclosure both fall short." } }),
  S(41, "code-records-coi",
    { type: "scenario", question: "You notice your FSP has no conflict-of-interest policy. This means the FSP is:", options: ["In breach", "Compliant, if no conflicts have arisen", "Exempt, if it is a small FSP", "Compliant, if conflicts are disclosed verbally"], correct: 0, feedback: { correct: "Every FSP must adopt and maintain one, whether or not a conflict has yet materialised.", incorrect: "It's a breach. A COI management policy is mandatory for all FSPs." } },
    { type: "mcq", question: "A COI management policy must provide for the FSP to:", options: ["Identify conflicts, avoid or mitigate them, and disclose them", "Eliminate all conflicts permanently", "Report every conflict to the Ombud", "Ignore conflicts below a threshold"], correct: 0, feedback: { correct: "Right. Elimination isn't realistic, which is why the standard is identify, mitigate, disclose.", incorrect: "Identify, avoid or mitigate, and disclose." } }),
  S(42, "fit-and-proper",
    { type: "scenario", question: "An FSP is solvent, its staff are qualified and honest, but it has no systems, no records and no compliance capacity. Which fit and proper pillar fails?", options: ["Operational ability", "Financial soundness", "Honesty and integrity", "Competence"], correct: 0, feedback: { correct: "Operational ability covers the infrastructure to actually deliver the service, systems, records and controls, not just people.", incorrect: "Operational ability. Solvency, honesty and qualifications are all intact; the missing pillar is the capacity to operate properly." } },
    { type: "scenario", question: "A representative is technically excellent and the FSP is well run, but they are under sequestration. Which pillar is in question?", options: ["Financial soundness", "Competence", "Operational ability", "None. Personal finances are irrelevant"], correct: 0, feedback: { correct: "Financial soundness asks whether the person or FSP is insolvent or under financial disability. Sequestration goes straight to it.", incorrect: "Financial soundness. Personal insolvency is directly relevant to fit and proper status." } }),
  S(43, "tcf-complaints",
    { type: "scenario", question: "A client sends their complaint straight to the FAIS Ombud without contacting the FSP first. What is the likely response?", options: ["The Ombud will normally refer it back so the FSP has its chance to resolve it", "The Ombud will determine it immediately", "The complaint will be permanently barred", "The FSCA will take it over"], correct: 0, feedback: { correct: "The Ombud is an escalation route. The FSP gets its six weeks first, and only then does the referral window open.", incorrect: "It goes back to the FSP first. The Ombud is an escalation, not a starting point, and the complaint isn't lost." } },
    { type: "mcq", question: "How long does the FSP have to resolve an internal complaint before the Ombud route opens?", options: ["6 weeks", "6 months", "30 days", "3 years"], correct: 0, feedback: { correct: "Right. Six weeks internally, then six months to refer to the Ombud.", incorrect: "Six weeks. The client then has six months to refer it onward." } }),
  S(44, "fais-purpose",
    { type: "scenario", question: "Under the Twin Peaks model, which question does the Prudential Authority exist to answer?", options: ["Can this institution meet its obligations and stay solvent?", "Is this institution treating its customers fairly?", "Is this adviser properly licensed?", "Was this client given suitable advice?"], correct: 0, feedback: { correct: "Solvency and systemic soundness. The remaining three are all FSCA or FAIS Ombud territory.", incorrect: "Whether the institution is safe and sound. Conduct, licensing and advice quality sit with the FSCA and the Ombud." } },
    { type: "scenario", question: "A bank treats customers fairly but its capital position deteriorates badly. Which regulator leads?", options: ["The Prudential Authority", "The FSCA", "The FAIS Ombud", "The National Credit Regulator"], correct: 0, feedback: { correct: "Right. Solvency is the Prudential Authority's mandate; conduct is fine here.", incorrect: "The Prudential Authority handles safety and soundness." } }),
  S(45, "code-general-duty",
    { type: "scenario", question: "A busy client says 'just sign it for me, you know what I want' and asks you to complete and submit the application yourself. You should:", options: ["Refuse. The client must review and sign the completed document themselves", "Sign it, since you have their verbal authority", "Sign it and note the instruction on file", "Ask a colleague to witness you signing"], correct: 0, feedback: { correct: "Verbal authority doesn't let you sign for a client, and a file note doesn't fix it. The client must see what they're agreeing to.", incorrect: "Refuse. Signing on a client's behalf isn't cured by verbal authority, a file note or a witness." } },
    { type: "scenario", question: "You discover you gave incorrect fee information to a client last week. You should:", options: ["Correct it promptly in writing and update your records", "Wait to see whether it becomes an issue", "Correct it verbally at the next meeting", "Do nothing, as the transaction has completed"], correct: 0, feedback: { correct: "Right. Prompt written correction is what due skill, care and diligence requires.", incorrect: "Correct it promptly in writing and update the records." } }),
  S(46, "fais-ombud",
    { type: "mcq", question: "A determination amount unpaid by an FSP can be:", options: ["Enforced as if it were a court order", "Written off after a year", "Recovered only through a fresh civil action", "Collected by the FSCA"], correct: 0, feedback: { correct: "That enforceability is what makes the Ombud process meaningful rather than advisory.", incorrect: "Enforced as if it were a court order." } },
    { type: "scenario", question: "An FSP treats an Ombud determination as advice it may take or leave. Why is that a serious misreading?", options: ["A determination is binding and enforceable as if a court had made it", "Because the FSCA will fine them for the delay", "Because the client can appeal to the Constitutional Court", "Because the licence lapses automatically"], correct: 0, feedback: { correct: "It carries the force of a court order. The only proper route to challenge it is reconsideration by the Tribunal.", incorrect: "Determinations are binding and enforceable like court orders, not recommendations." } }),
  S(47, "tcf-complaints",
    { type: "scenario", question: "A firm has excellent sales-stage disclosure but makes claims slow and switching difficult. Does it meet the TCF standard?", options: ["No. TCF applies across the whole product life cycle, not just at the point of sale", "Yes, disclosure is the core requirement", "Yes, provided claims are eventually paid", "TCF applies only to advice, so it is irrelevant"], correct: 0, feedback: { correct: "Fair treatment has to survive past the sale. Post-sale barriers are precisely what Outcome 6 targets.", incorrect: "TCF covers design, sale, service, claims and complaints. Good disclosure at the sale doesn't cure obstruction afterwards." } },
    { type: "mcq", question: "Which is a TCF outcome?", options: ["Products perform as firms have led customers to expect", "Products are the cheapest available", "Firms achieve their sales targets", "All customers receive identical advice"], correct: 0, feedback: { correct: "Right. TCF is about meeting the expectations firms create, not about price or uniformity.", incorrect: "Products performing as customers were led to expect. Price and sales targets aren't TCF outcomes." } }),
  S(48, "fais-competence-cpd",
    { type: "mcq", question: "Which is required BEFORE a product-specific recommendation?", options: ["Product-specific training on that product", "A completed CPD cycle", "Five years of experience", "A Key Individual's written consent"], correct: 0, feedback: { correct: "You must understand the specific product. It sits alongside, not inside, the CPD requirement.", incorrect: "Product-specific training on that product." } },
    { type: "scenario", question: "A representative logs a full day of insurer product training and claims it against their CPD requirement. Is that correct?", options: ["No. Product-specific training is a separate obligation and does not earn CPD hours", "Yes, all training counts toward CPD", "Yes, if the insurer is accredited", "Yes, up to half the annual requirement"], correct: 0, feedback: { correct: "Three separate requirements travel together and get confused constantly: CPD, class-of-business training, and product-specific training.", incorrect: "Product-specific training sits outside CPD. It's required in its own right, but it doesn't earn CPD hours." } }),
  S(49, "code-general-duty",
    { type: "scenario", question: "A nervous retiree says they will only invest if you promise the capital is completely safe. The product is a moderate-risk unit trust. You should:", options: ["Explain honestly that capital is not guaranteed, and reconsider whether this product suits them at all", "Reassure them that it is safe enough in practice", "Promise it verbally but not in writing", "Proceed on an against-advice basis"], correct: 0, feedback: { correct: "Note the second half: their need for capital certainty is itself suitability information. The honest answer may be a different product.", incorrect: "Never promise capital safety you can't deliver. Their insistence on certainty is a suitability signal, not an objection to talk them out of." } },
    { type: "scenario", question: "A client pressures you to say a product is 'risk-free' so they feel comfortable signing. You should:", options: ["Describe the actual risks accurately, even if it costs you the sale", "Agree, since they have already decided", "Say it is 'low risk' as a compromise", "Have a colleague say it instead"], correct: 0, feedback: { correct: "Right. The duty runs to the client's interests, not to closing the sale, and mislabelling risk is exactly what Ombud determinations turn on.", incorrect: "Describe the risks accurately. Softening the language to secure a signature is a breach." } }),
  S(50, "code-general-duty",
    { type: "scenario", question: "Faced with a situation the Code does not expressly address, which principle should guide a representative's decision?", options: ["Act honestly and fairly", "Do whatever the contract permits", "Follow the product supplier's guidance", "Choose the option that protects the FSP"], correct: 0, feedback: { correct: "The general duty is the fallback precisely because no code can list every situation. Every specific rule is an application of it.", incorrect: "Fall back on the general duty: honestly, fairly, with due skill, care and diligence, in the client's interests." } },
    { type: "scenario", question: "An adviser insists they complied because 'no specific rule says I couldn't'. Why is that reasoning unsafe under FAIS?", options: ["The General Code imposes an overarching duty that applies even where no specific rule is engaged", "Because the FSCA publishes new rules monthly", "Because the client can always complain", "Because contracts override the Code"], correct: 0, feedback: { correct: "The Code is principles-based. 'No rule prohibited it' is not a defence if the conduct failed the general duty.", incorrect: "An overarching duty applies throughout. The absence of a specific prohibition doesn't make conduct compliant." } }),
];

